@Test
public void testPrepareWithFail() throws Exception {
    Map<String, Object> topoConf = new HashMap<>();
    KeyValueState<String, CheckPointState> state = (KeyValueState<String, CheckPointState>) StateFactory.getState("__state", topoConf, mockTopologyContext);
    CheckPointState txState = new CheckPointState(-1, COMMITTED);
    state.put("__state", txState);
    spout.open(mockTopologyContext, mockOutputCollector, 0, state);
    ArgumentCaptor<String> stream = ArgumentCaptor.forClass(String.class);
    ArgumentCaptor<Values> values = ArgumentCaptor.forClass(Values.class);
    ArgumentCaptor<Object> msgId = ArgumentCaptor.forClass(Object.class);
    spout.nextTuple();
    spout.ack(-1L);
    Utils.sleep(10);
    spout.nextTuple();
    spout.ack(0L);
    Utils.sleep(10);
    spout.nextTuple();
    spout.ack(0L);
    Utils.sleep(10);
    spout.nextTuple();
    spout.fail(1L);
    Utils.sleep(10);
    spout.nextTuple();
    spout.fail(1L);
    Utils.sleep(10);
    spout.nextTuple();
    spout.ack(1L);
    Utils.sleep(10);
    spout.nextTuple();
    spout.ack(0L);
    Utils.sleep(10);
